pub fn extract(path: &str, source: &str) -> Result<Vec<Requirement>> {
    let paragraphs: Vec<_> = Parser::new(source)
        .into_offset_iter()
        .filter_map(|(event, range)| matches!(event, Event::Start(Tag::Paragraph)).then_some(range))
        .collect();
    let mut requirements = Vec::new();
    let mut used = BTreeSet::new();
    for role in roles(source).into_iter().filter(|r| r.name == "req") {
        if !valid_id(&role.label) || !role.label.contains('.') {
            return Err(format!("{path}: invalid requirement ID {:?}", role.label));
        }
        let paragraph = paragraphs
            .iter()
            .find(|r| r.start <= role.range.start && r.end >= role.range.end)
            .ok_or_else(|| format!("{path}: {} must begin a paragraph", role.label))?;
        if !source[paragraph.start..role.range.start].trim().is_empty()
            || !used.insert(paragraph.start)
        {
            return Err(format!(
                "{path}: {} must be the only definition at the start of its paragraph",
                role.label
            ));
        }
        let text = source[role.range.end..paragraph.end].trim();
        if text.is_empty() {
            return Err(format!("{path}: {} has no requirement text", role.label));
        }
        requirements.push(Requirement {
            id: role.label,
            path: path.into(),
            line: source[..role.range.start]
                .bytes()
                .filter(|b| *b == b'\n')
                .count()
                + 1,
            requirement: text.into(),
        });
    }
    Ok(requirements)
}

pub fn roles(source: &str) -> Vec<Role> {
    let mut result = Vec::new();
    let mut nested_link = 0;
    for (event, range) in Parser::new(source).into_offset_iter() {
        match event {
            Event::Start(Tag::Link { .. } | Tag::Image { .. }) => nested_link += 1,
            Event::End(TagEnd::Link | TagEnd::Image) => nested_link -= 1,
            Event::Code(label) if nested_link == 0 => {
                let prefix = &source[..range.start];
                if !prefix.ends_with('}') {
                    continue;
                }
                let Some(start) = prefix.rfind('{') else {
                    continue;
                };
                let escapes = prefix[..start]
                    .bytes()
                    .rev()
                    .take_while(|b| *b == b'\\')
                    .count();
                if escapes % 2 != 0 {
                    continue;
                }
                let name = &prefix[start + 1..prefix.len() - 1];
                if name == "req" || (valid_id(name) && name.contains('.')) {
                    result.push(Role {
                        range: start..range.end,
                        name: name.into(),
                        label: label.into_string(),
                    });
                }
            }
            _ => {}
        }
    }
    result
}

fn extracts_multiline_markdown_and_ignores_examples() {
    let source = "# Header

```md
{req}`fake.fenced` Nope.
```

    {req}`fake.indented` Nope.

``{req}`fake.inline` ``

\{req}`fake.escaped` Nope.

[{req}`fake.link`](url)

![{req}`fake.image`](image.png)

{req}`real.rule` Keep **all** data,
including {other.rule}`references`.

Rationale is separate.
";
    let requirements = extract("chapter.md", source).unwrap();
    assert_eq!(requirements.len(), 1);
    assert_eq!(requirements[0].id, "real.rule");
    assert_eq!(
        requirements[0].requirement,
        "Keep **all** data,
including {other.rule}`references`."
    );
    assert_eq!(
        source.lines().nth(requirements[0].line - 1).unwrap(),
        "{req}`real.rule` Keep **all** data,"
    );
}
